#include <iostream>
#include <string>

#include "Halide.h"

// include common definitions (defines DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "mvt.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization translated to Halide.
 *
 * Original C:
 *   for (i = 0; i < n; i++) {
 *     x1[i]  = (DATA_TYPE) (i % n) / n;
 *     x2[i]  = (DATA_TYPE) ((i + 1) % n) / n;
 *     y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
 *     y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
 *     for (j = 0; j < n; j++)
 *       A[i][j] = (DATA_TYPE) (i*j % n) / n;
 *   }
 *
 * We keep the same formulas and layout, but use Halide for
 * initialization and add a cache‑friendly, parallel schedule.
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 1> x1,
                Halide::Buffer<num_t, 1> x2,
                Halide::Buffer<num_t, 1> y_1,
                Halide::Buffer<num_t, 1> y_2,
                Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");

    Func init_x1("init_x1");
    Func init_x2("init_x2");
    Func init_y1("init_y1");
    Func init_y2("init_y2");
    Func init_A("init_A");

    // Precompute 1/n as an Expr of type num_t to avoid repeated division
    Expr n_expr  = cast<num_t>(n);
    Expr inv_n   = cast<num_t>(1) / n_expr;

    // 1D vectors
    init_x1(i) = cast<num_t>(i % n) * inv_n;
    init_x2(i) = cast<num_t>((i + 1) % n) * inv_n;
    init_y1(i) = cast<num_t>((i + 3) % n) * inv_n;
    init_y2(i) = cast<num_t>((i + 4) % n) * inv_n;

    // 2D matrix A: C layout A[i][j] -> Halide A(j, i)
    // First dimension (j) is contiguous in memory.
    init_A(j, i) = cast<num_t>((i * j) % n) * inv_n;

    // ------------------------------------------------------------------
    // Initialization schedule
    //
    // We parallelize across the outer index and vectorize the inner
    // index for 1D arrays. These constants can be tuned for a given
    // machine.
    // ------------------------------------------------------------------
    constexpr int VEC_WIDTH_1D = 8;   // tune: SIMD width for 1D init
    Var io("io"), ii("ii");

    init_x1
        .split(i, io, ii, VEC_WIDTH_1D)
        .parallel(io)
        .vectorize(ii);
    init_x2
        .split(i, io, ii, VEC_WIDTH_1D)
        .parallel(io)
        .vectorize(ii);
    init_y1
        .split(i, io, ii, VEC_WIDTH_1D)
        .parallel(io)
        .vectorize(ii);
    init_y2
        .split(i, io, ii, VEC_WIDTH_1D)
        .parallel(io)
        .vectorize(ii);

    // For A we parallelize over rows (i) and vectorize over columns (j),
    // which are contiguous in memory.
    constexpr int VEC_WIDTH_A = 8;    // tune: SIMD width across j
    Var jo("jo"), ji("ji");

    init_A
        .split(j, jo, ji, VEC_WIDTH_A)
        .parallel(i)
        .vectorize(ji);

    // Realize into the provided buffers
    init_x1.realize(x1);
    init_x2.realize(x2);
    init_y1.realize(y_1);
    init_y2.realize(y_2);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to:
    //   DATA_TYPE A[N][N];
    //   DATA_TYPE x1[N], x2[N], y_1[N], y_2[N];
    //
    // PolyBench uses A[i][j]; we map j -> dim 0 (x), i -> dim 1 (y).
    Halide::Buffer<num_t, 2> A(n, n);     // (j, i)
    Halide::Buffer<num_t, 1> x1(n);
    Halide::Buffer<num_t, 1> x2(n);
    Halide::Buffer<num_t, 1> y_1(n);
    Halide::Buffer<num_t, 1> y_2(n);

    // ImageParams to feed into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    // Initialize data using a Halide-based initializer
    init_array(n, x1, x2, y_1, y_2, A);

    // Bind buffers to ImageParams
    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // Halide translation of kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Mathematically:
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //
    // With our (j, i) mapping for A[i][j]:
    //   A[i][j]  -> A_param(j, i)
    //   A[j][i]  -> A_param(i, j)

    Var i("i");
    // Use the width of A (dim 0, corresponding to j) as the reduction extent.
    RDom r(0, A.dim(0).extent(), "r");

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First loop nest: accumulate into x1
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second loop nest: accumulate into x2
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // ------------------------------------------------------------------
    // Scheduling for the MVT kernels
    //
    // We parallelize across i (rows). Each i is independent, so this
    // matches the original C loop nest semantics while exploiting
    // multi-core parallelism. We keep the reduction loop over r
    // serial inside each thread to preserve a simple, cache-friendly
    // streaming access in r.
    //
    // TILE_I_PAR is a tunable chunk size: it controls how many rows
    // each worker thread processes, and thus how many parallel tasks
    // are created (≈ n / TILE_I_PAR).
    // ------------------------------------------------------------------
    constexpr int TILE_I_PAR = 64;  // tune: rows per parallel chunk

    Var i_outer1("i_outer1"), i_inner1("i_inner1");
    Var i_outer2("i_outer2"), i_inner2("i_inner2");

    // x1 kernel schedule
    mvt_x1.compute_root();
    // Pure definition: split i into outer (for parallelism) and inner.
    mvt_x1
        .split(i, i_outer1, i_inner1, TILE_I_PAR)
        .parallel(i_outer1);
    // Update definition: use the same splitting / parallelization.
    mvt_x1.update()
        .split(i, i_outer1, i_inner1, TILE_I_PAR)
        .parallel(i_outer1);
    // (Reduction variable r remains the innermost loop inside each
    // thread; Halide's codegen can still autovectorize within r.)

    // x2 kernel schedule
    mvt_x2.compute_root();
    mvt_x2
        .split(i, i_outer2, i_inner2, TILE_I_PAR)
        .parallel(i_outer2);
    mvt_x2.update()
        .split(i, i_outer2, i_inner2, TILE_I_PAR)
        .parallel(i_outer2);

    // JIT-compile the two Funcs for the host target
    Target target = get_host_target();
    mvt_x1.compile_jit(target);
    mvt_x2.compile_jit(target);

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize back into x1 and x2 buffers (in-place relative to the C view)
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1(idx) << '\n';
        }
        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
