    //
    // After split, the iteration vars are (r, i_outer2, i_inner2).
    // We reorder them so that:
    //   * i_inner2 is innermost (vectorized, contiguous along A_param's x-dim)
    //   * r is in the middle (reduction over rows j)
    //   * i_outer2 is outermost (parallelized)
    mvt_x2.update()
        .split(i, i_outer2, i_inner2, tile_i)
        .reorder(i_inner2, r, i_outer2)
        .parallel(i_outer2)
        .vectorize(i_inner2, vec_width);

