#include "defines.hpp"

// include benchmark-specific definitions
#include "mvt.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization translated to Halide.
 *
 * Original C:
 *   for (i = 0; i < n; i++) {
 *     x1[i]  = (DATA_TYPE) (i % n) / n;
 *     x2[i]  = (DATA_TYPE) ((i + 1) % n) / n;
 *     y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
 *     y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
 *     for (j = 0; j < n; j++)
 *       A[i][j] = (DATA_TYPE) (i*j % n) / n;
 *   }
 *
 * We keep the same math and use Halide scheduling to get good
 * vectorization and parallelism on a modern x64 CPU.
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 1> x1,
                Halide::Buffer<num_t, 1> x2,
                Halide::Buffer<num_t, 1> y_1,
                Halide::Buffer<num_t, 1> y_2,
                Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");

    Func init_x1("init_x1");
    Func init_x2("init_x2");
    Func init_y1("init_y1");
    Func init_y2("init_y2");
    Func init_A("init_A");

    // 1D vectors
    // Keep expressions identical to the original code for bitwise
    // equivalence; Halide will treat 'n' as a constant captured by
    // the JIT-compiled pipeline.
    init_x1(i) = cast<num_t>(i % n)        / cast<int>(n);
    init_x2(i) = cast<num_t>((i + 1) % n)  / cast<int>(n);
    init_y1(i) = cast<num_t>((i + 3) % n)  / cast<int>(n);
    init_y2(i) = cast<num_t>((i + 4) % n)  / cast<int>(n);

    // 2D matrix A: C layout A[i][j] -> Halide A(j, i)
    //   C: A[i][j]
    //   Halide buffer: A(j, i)
    init_A(j, i) = cast<num_t>((i * j) % n) / cast<int>(n);

    // -----------------------------------------------------------------
    // Scheduling for initialization
    // -----------------------------------------------------------------
    // Use the host JIT target to pick a reasonable vector width (e.g. 8
    // for AVX2 double, 16 for AVX2 float).
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // 1D initializations: split the i loop into [i_outer][i_inner],
    // parallelize outer, vectorize inner.
    {
        Var i_outer("i_outer"), i_inner("i_inner");

        init_x1
            .compute_root()
            .split(i, i_outer, i_inner, vec_width)
            .parallel(i_outer)
            .vectorize(i_inner);

        init_x2
            .compute_root()
            .split(i, i_outer, i_inner, vec_width)
            .parallel(i_outer)
            .vectorize(i_inner);

        init_y1
            .compute_root()
            .split(i, i_outer, i_inner, vec_width)
            .parallel(i_outer)
            .vectorize(i_inner);

        init_y2
            .compute_root()
            .split(i, i_outer, i_inner, vec_width)
            .parallel(i_outer)
            .vectorize(i_inner);
    }

    // 2D matrix initialization:
    // Dimension 0 (j) is contiguous in memory, so we vectorize it;
    // dimension 1 (i) is the outer dimension, so we parallelize it.
    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the provided buffers
    init_x1.realize(x1);
    init_x2.realize(x2);
    init_y1.realize(y_1);
    init_y2.realize(y_2);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to:
    //   DATA_TYPE A[N][N];
    //   DATA_TYPE x1[N], x2[N], y_1[N], y_2[N];
    //
    // PolyBench uses A[i][j]; we map j -> dim 0 (x), i -> dim 1 (y).
    Halide::Buffer<num_t, 2> A(n, n);     // (j, i)
    Halide::Buffer<num_t, 1> x1(n);
    Halide::Buffer<num_t, 1> x2(n);
    Halide::Buffer<num_t, 1> y_1(n);
    Halide::Buffer<num_t, 1> y_2(n);

    // ImageParams to feed into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    // Initialize data using a Halide-based initializer
    init_array(n, x1, x2, y_1, y_2, A);

    // Bind buffers to ImageParams
    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // Halide translation of kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Mathematically:
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //
    // With our (j, i) mapping for A[i][j]:
    //   A[i][j]  -> A_param(j, i)
    //   A[j][i]  -> A_param(i, j)

    Var i("i");
    // Use the width of A (dim 0, corresponding to j) as the reduction extent.
    RDom r(0, A.dim(0).extent(), "r");

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First loop nest: accumulate into x1
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   A[i][j] -> A_param(j, i)
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second loop nest: accumulate into x2
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //   A[j][i] -> A_param(i, j)
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // -----------------------------------------------------------------
    // Scheduling for kernel_mvt
    // -----------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Compute both results at root so we can parallelize over i.
    mvt_x1.compute_root();
    mvt_x2.compute_root();

    // Bound i to [0, n) to make the schedule explicit.
    mvt_x1.bound(i, 0, n);
    mvt_x2.bound(i, 0, n);

    // For each Func:
    //  - Split 'i' into [i_outer][i_inner]
    //  - Parallelize outer over threads
    //  - Vectorize inner across i
    // This preserves the original semantics (no cross-i dependencies)
    // while exploiting 32 cores and SIMD.
    {
        Var i_outer("i_outer"), i_inner("i_inner");

        mvt_x1
            .split(i, i_outer, i_inner, vec_width)
            .parallel(i_outer)
            .vectorize(i_inner);

        mvt_x1.update()
            .split(i, i_outer, i_inner, vec_width)
            .parallel(i_outer)
            .vectorize(i_inner);
    }
    {
        Var i_outer2("i_outer2"), i_inner2("i_inner2");

        mvt_x2
            .split(i, i_outer2, i_inner2, vec_width)
            .parallel(i_outer2)
            .vectorize(i_inner2);

        mvt_x2.update()
            .split(i, i_outer2, i_inner2, vec_width)
            .parallel(i_outer2)
            .vectorize(i_inner2);
    }

    // JIT-compile the two Funcs for the chosen target. We compile
    // ahead of timing so compilation time is not included.
    mvt_x1.compile_jit(target);
    mvt_x2.compile_jit(target);

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize back into x1 and x2 buffers (in-place relative to the C view)
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1(idx) << '\n';
        }
        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
